import { BREAKPOINTS } from '@westpac/style-config/constants';
const BREAKPOINTS_DECRESCENT = Object.keys(BREAKPOINTS).reverse();
export function ensureBreakpoint(breakpointsProvided, breakpoint) {
    const currentBreakpointIndex = BREAKPOINTS_DECRESCENT.findIndex((bp)=>bp === breakpoint);
    const finalBreakPoint = [
        breakpoint,
        ...BREAKPOINTS_DECRESCENT.slice(currentBreakpointIndex),
        'initial'
    ].find((currentBreakpoint)=>breakpointsProvided.includes(currentBreakpoint));
    return finalBreakPoint;
}
export function resolveResponsiveVariant(variant, breakpoint) {
    if (typeof variant !== 'object') {
        return variant;
    }
    const finalBreakpoint = ensureBreakpoint(Object.keys(variant), breakpoint);
    return variant[finalBreakpoint];
}
